\mathsf{State}_{\mathsf R}
=
\{S:S\text{ 是从 }\mathsf{Hole}_{\mathsf R}\text{ 到 }\mathsf{Goal}_{\mathsf R}\text{ 的有限偏函数}\}.

\mathsf{GoalStack}_{\mathsf R}
=
\{(h_0:G_0,\ldots,h_{n-1}:G_{n-1}):n\in\mathbb N,\ h_i\in\mathsf{Hole}_{\mathsf R},\ G_i=(\Gamma_i\Rightarrow A_i)\in\mathsf{Goal}_{\mathsf R},\ \forall i,j<n\ (i\ne j\Rightarrow h_i\ne h_j)\}.

\mathsf{Jud}_{\mathsf R}
=
\{\Gamma\vdash p:A:p\in\mathsf{Prf}_{\mathsf R},\ A\in\mathsf{Ty}_{\mathsf R},\Gamma\in\mathsf{Ctx}_{\mathsf R},FV(p)\cup FV(A)\subseteq\operatorname{dom}\Gamma\},

\mathsf{RuleImp}_{\mathsf R}
=
\{(\langle\Gamma,x:A\vdash p:B\rangle,\Gamma\vdash\lambda x.p:A\to B)\}
\cup
\{(\langle\Gamma\vdash p:A\to B,\Gamma\vdash q:A\rangle,\Gamma\vdash p\,q:B)\}.

\mathsf{RuleAnd}_{\mathsf R}
=
\{(\langle\Gamma\vdash p:A,\Gamma\vdash q:B\rangle,\Gamma\vdash\langle p,q\rangle:A\land B)\}
\cup
\{(\langle\Gamma\vdash p:A\land B\rangle,\Gamma\vdash\pi_1(p):A)\}
\cup
\{(\langle\Gamma\vdash p:A\land B\rangle,\Gamma\vdash\pi_2(p):B)\}.

\mathsf{RuleForall}_{\mathsf R}
=
\{(\langle\Gamma,x:A\vdash p:B\rangle,\Gamma\vdash\Lambda x.p:\forall x:A.B)\}
\cup
\{(\langle\Gamma\vdash p:\forall x:A.B,\Gamma\vdash t:A\rangle,
\Gamma\vdash p\,t:B\langle x:=t\rangle_{\mathsf{Ty}})\}.

\mathsf{Rule}_{\mathsf R}
=
\mathsf{RuleVar}_{\mathsf R}
\cup\mathsf{RuleTop}_{\mathsf R}
\cup\mathsf{RuleImp}_{\mathsf R}
\cup\mathsf{RuleAnd}_{\mathsf R}
\cup\mathsf{RuleOr}_{\mathsf R}
\cup\mathsf{RuleForall}_{\mathsf R}
\cup\mathsf{RuleExists}_{\mathsf R}.
